void outgoing_win_active(lv_obj_t *win, void *p_param)
{
    char num[CALL_PHONE_NUMBER_LEN_MAX] = {0};

    ui_outgoing_init();
    /* display call number */
    call_flow_get_phonenum(num);
    if(call_flow_is_emergency_number(num)) {
        lv_label_set_text(ui_LblOutgoingPhoneNum, "Emergency Number");
    }else {
        lv_label_set_text(ui_LblOutgoingPhoneNum, num);
    }
}

